import {ChartCard} from '@github-ui/chart-card'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import type {
  dashboardRoute,
  orgDashboardRoute,
  stafftoolsDashboardRoute,
  stafftoolsOrgDashboardRoute,
} from '../routes/dashboard-route'
import styles from './RuleSuitesChart.module.css'

type DashboardRouteConfig =
  | typeof dashboardRoute
  | typeof orgDashboardRoute
  | typeof stafftoolsDashboardRoute
  | typeof stafftoolsOrgDashboardRoute

export function RuleSuitesChart({routeConfig}: {routeConfig: DashboardRouteConfig}) {
  const {
    data: {ruleSuites},
  } = useRouteQuery(routeConfig, 'mainQuery')
  const tickPositions = ruleSuites[0]?.data.map(([timestamp]) => timestamp) ?? undefined
  return (
    <ChartCard size="medium" className={styles.RuleSuitesChartWrapper}>
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <ChartCard.Title as="h2">Rule Suites</ChartCard.Title>
      <ChartCard.LineChart series={ruleSuites} options={{xAxis: {type: 'datetime', tickPositions}}} />
    </ChartCard>
  )
}
